  1	import React from 'react';
  2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
  3	import { MemoryRouter } from 'react-router-dom';
  4	import { Box } from '@chakra-ui/react';
  5	import { expect, within } from 'storybook/test';
  6	import { StaticProductHeader } from './staticProductHeader';
  7	
  8	/*
  9	 * A reasoned deviation from components.md's "Pages get a story showing the full assembly with
 10	 * representative props — not a story per sub-section", declared in the PR body rather than
 11	 * presented as compliance. Storying the PDP itself would mean stubbing ~30 hook call sites
 12	 * including `useProduct`, which cuts against the direction to prefer real SFCC data; #59 set
 13	 * the precedent of storying the presentational `Footer` rather than the fetching container.
 14	 */
 15	
 16	/** Real Shopper Products fields for 8637DS241 (ZimmermannAU, 2026-08-23). */
 17	const PRODUCT = {
 18	  id: '8637DS241-BLUEB-6',
 19	  name: 'Natura Long Sleeve Linen Mini Dress',
 20	  longDescription:
 21	    '<p>A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.</p>',
 22	  master: { masterId: '8637DS241' },
 23	  c_modelFit: 'Model is 178cm / 5ft 10in and wears a size 1.',
 24	  price: 795,
 25	  productPromotions: [{ promotionId: 'final-sale', calloutMsg: 'Final sale — no returns' }],
 26	};
 27	
 28	const meta: Meta<typeof StaticProductHeader> = {
 29	  title: 'Commerce/StaticProductHeader',
 30	  component: StaticProductHeader,
 31	  argTypes: {
 32	    name: { control: 'text' },
 33	    currency: { control: 'text' },
 34	    isProductPartOfBundle: { control: 'boolean' },
 35	  },
 36	  decorators: [
 37	    (Story: React.ComponentType) => (
 38	      // MemoryRouter because the base `Breadcrumb` renders react-router `Link`s, which throw
 39	      // outside a Router — preview.tsx supplies Chakra and IntlProvider, but no Router.
 40	      // 218px is the DS info-column width, the same frame zimmProductContent's story uses, so
 41	      // the name's wrap behaviour here matches the real column.
 42	      <MemoryRouter>
 43	        <Box width="218px">
 44	          <Story />
 45	        </Box>
 46	      </MemoryRouter>
 47	    ),
 48	  ],
 49	};
 50	export default meta;
 51	
 52	type Story = StoryObj<typeof StaticProductHeader>;
 53	
 54	export const Default: Story = {
 55	  name: 'Full product — everything renders',
 56	  args: {
 57	    name: PRODUCT.name,
 58	    product: PRODUCT,
 59	    priceData: { currentPrice: 795 },
 60	    currency: 'AUD',
 61	    category: [
 62	      { id: 'womens', name: 'Womens' },
 63	      { id: 'womens-clothing-dresses', name: 'Dresses' },
 64	    ],
 65	    isProductPartOfBundle: false,
 66	  },
 67	  play: async ({ canvasElement }) => {
 68	    const canvas = within(canvasElement);
 69	
 70	    // h2, not h1: the page owns the h1 (a screen-reader-only "Product Details"), so this is
 71	    // the constraint the extraction had to preserve rather than quietly re-level.
 72	    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();
 73	
 74	    // Breadcrumb and promo callout are reproduced from the base header rather than dropped,
 75	    // because `renderHeader` replaces the whole block — assert both survived the move.
 76	    await expect(canvas.getByRole('link', { name: 'Dresses' })).toBeInTheDocument();
 77	    await expect(canvas.getByTestId('promo-callout')).toBeInTheDocument();
 78	
 79	    // Formatted by the partial's own `useIntl()`, under preview.tsx's en-AU IntlProvider.
 80	    await expect(canvas.getByTestId('product-price')).toHaveTextContent('795');
 81	    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
 82	  },
 83	};
 84	
 85	export const NameOnly: Story = {
 86	  name: 'Product absent, name present — price collapses',
 87	  // ProductView passes `name: product?.name` alongside `product`, so during a variant fetch the
 88	  // name can be known while the product is not. `headerProduct ?? { name }` is the path that
 89	  // keeps the title rendered instead of dropping back to a skeleton.
 90	  args: {
 91	    name: PRODUCT.name,
 92	    product: undefined,
 93	    priceData: undefined,
 94	    currency: 'AUD',
 95	    isProductPartOfBundle: false,
 96	  },
 97	  play: async ({ canvasElement }) => {
 98	    const canvas = within(canvasElement);
 99	
100	    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();
101	
102	    // No priceData means the mapper yields '' rather than a formatted NaN, and the price atom
103	    // renders nothing — so the group collapses to one row instead of reserving an empty one.
104	    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
105	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
106	
107	    // `product` is what gates the promo, so it stays a bare skeleton here.
108	    await expect(canvas.queryByTestId('promo-callout')).not.toBeInTheDocument();
109	  },
110	};
111	
112	export const Loading: Story = {
113	  name: 'Neither — the state every page load starts in',
114	  args: {},
115	  play: async ({ canvasElement }) => {
116	    const canvas = within(canvasElement);
117	
118	    // `selectPdpProductInfo` returns null without a name, so the content group is absent and
119	    // only the reserve is on screen.
120	    await expect(canvas.queryByTestId('product-content')).not.toBeInTheDocument();
121	
122	    // The reserve itself (D17). An empty SFCC `Skeleton` measures 0px — its baseStyle sets only
123	    // borderRadius and opacity — so without the explicit minHeight the title would shove the
124	    // page down when it resolves. 18px is `lineHeights['2xs']` (1.125rem), which is what
125	    // `--zimm-font-lineheight-2xs` derives from and what ZimmProductName's heading3 renders at.
126	    // Asserted on the first skeleton by position because an empty one carries no accessible
127	    // name or test id to select it by, and adding one would change the page's rendered output.
128	    const reserve = canvasElement.querySelector('.chakra-skeleton');
129	    await expect(reserve).not.toBeNull();
130	    await expect(getComputedStyle(reserve as Element).minHeight).toBe('18px');
131	  },
132	};

