import React from 'react';
import { describe, test, expect } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import type { ProductViewHeaderProps } from 'app/components/product-view';
import { BaselineHost } from './baseline';
import { StaticProductHeader } from 'app/pages/product-detail/partials/staticProductHeader';

const PRODUCT = {
  id: '8637DS241-BLUEB-6',
  name: 'Natura Long Sleeve Linen Mini Dress',
  longDescription: '<p>A long sleeve linen mini dress featuring a deep v-neckline.</p>',
  master: { masterId: '8637DS241' },
  c_modelFit: 'Model is 178cm / 5ft 10in and wears a size 1.',
  productPromotions: [{ promotionId: 'final-sale', calloutMsg: 'Final sale' }],
};
const CATS = [
  { id: 'womens', name: 'Womens' },
  { id: 'womens-clothing-dresses', name: 'Dresses' },
];

// 9 prop sets: the builder's 4 plus 5 the builder did not claim.
const CASES: Record<string, ProductViewHeaderProps> = {
  '1 full product': { name: PRODUCT.name, product: PRODUCT as never, priceData: { currentPrice: 795 }, currency: 'AUD', category: CATS as never, isProductPartOfBundle: false },
  '2 name only (no product)': { name: PRODUCT.name, product: undefined, priceData: undefined, currency: 'AUD', isProductPartOfBundle: false },
  '3 neither (initial load)': {},
  '4 part of bundle': { name: PRODUCT.name, product: PRODUCT as never, priceData: { currentPrice: 795 }, currency: 'AUD', category: CATS as never, isProductPartOfBundle: true },
  '5 product, no promotions': { name: PRODUCT.name, product: { ...PRODUCT, productPromotions: undefined } as never, priceData: { currentPrice: 795 }, currency: 'AUD', category: CATS as never, isProductPartOfBundle: false },
  '6 category only, no product/name': { category: CATS as never, currency: 'AUD' },
  '7 currency undefined (falls to "")': { name: PRODUCT.name, product: PRODUCT as never, priceData: { currentPrice: 795 }, currency: undefined, isProductPartOfBundle: false },
  '8 price 0 (falsy but numeric)': { name: PRODUCT.name, product: PRODUCT as never, priceData: { currentPrice: 0 }, currency: 'AUD', isProductPartOfBundle: false },
  '9 empty category array': { name: PRODUCT.name, product: PRODUCT as never, priceData: { currentPrice: 795 }, currency: 'AUD', category: [] as never, isProductPartOfBundle: false },
};

const wrap = (node: React.ReactNode, locale = 'en-AU') =>
  renderToStaticMarkup(
    <MemoryRouter>
      <ChakraProvider theme={theme}>
        <IntlProvider locale={locale} defaultLocale="en-AU">{node}</IntlProvider>
      </ChakraProvider>
    </MemoryRouter>,
  );

describe('COMMIT 5 — extraction equivalence', () => {
  for (const [label, props] of Object.entries(CASES)) {
    test(`markup identical: ${label}`, () => {
      const before = wrap(<BaselineHost {...props} />);
      const after = wrap(<StaticProductHeader {...props} />);
      expect(after).toBe(before);
    });
  }

  // Locale sensitivity: proves the partial reads the AMBIENT provider (same one the page read),
  // not a hardcoded/default locale. If it silently defaulted, de-DE would diverge from baseline.
  test('reads the ambient IntlProvider (de-DE grouping/symbol placement)', () => {
    const props = CASES['1 full product'];
    const before = wrap(<BaselineHost {...props} />, 'de-DE');
    const after = wrap(<StaticProductHeader {...props} />, 'de-DE');
    expect(after).toBe(before);
    expect(after).not.toBe(wrap(<StaticProductHeader {...props} />, 'en-AU'));
  });

  // ProductView mounts renderHeader at TWO sites (index.tsx:685 + :739). Both mount; one is
  // display:none. Prove the second instance is identical to the first => side-effect free.
  test('rendered twice per render: instance 2 identical to instance 1', () => {
    const props = CASES['1 full product'];
    const twice = wrap(
      <>
        <div id="a"><StaticProductHeader {...props} /></div>
        <div id="b"><StaticProductHeader {...props} /></div>
      </>,
    );
    const a = twice.split('<div id="b">')[0].replace('<div id="a">', '');
    const b = twice.split('<div id="b">')[1];
    expect(b.replace(/<\/div>$/, '')).toBe(a.replace(/<\/div>$/, ''));
    // and baseline rendered twice yields the same pair
    const twiceBase = wrap(
      <>
        <div id="a"><BaselineHost {...props} /></div>
        <div id="b"><BaselineHost {...props} /></div>
      </>,
    );
    expect(twice).toBe(twiceBase);
  });
});
